                StiTextRenderer.parseTagIntoPairs = function (tag) {
                    var attr = new List();
                    var pos = 0;
                    while ((pos < tag.length) && (tag[pos] == " "))
                        pos++;
                    while (pos < tag.length) {
                        var pos2 = pos;
                        var pair = new TagPair();
                        while ((pos2 < tag.length) && (tag[pos2] != " ") && (tag[pos2] != "="))
                            pos2++;
                        pair.keyBase = tag.substr(pos, pos2 - pos);
                        pair.key = pair.keyBase.toLowerCase();
                        pos = pos2;
                        while ((pos < tag.length) && (tag[pos] == " "))
                            pos++;
                        if ((pos < tag.length) && (tag[pos] == "=")) {
                            pos++;
                            while ((pos < tag.length) && (tag[pos] == " "))
                                pos++;
                            if (pos < tag.length) {
                                if (tag[pos] == '"') {
                                    pos++;
                                    pos2 = pos;
                                    while ((pos2 < tag.length) && (tag[pos2] != '"'))
                                        pos2++;
                                    pair.value = tag.substr(pos, pos2 - pos);
                                    pos = pos2;
                                    pos++;
                                }
                                else {
                                    pos2 = pos;
                                    while ((pos2 < tag.length) && (tag[pos2] != " "))
                                        pos2++;
                                    pair.value = tag.substr(pos, pos2 - pos);
                                    pos = pos2;
                                }
                            }
                        }
                        while ((pos < tag.length) && (tag[pos] == " "))
                            pos++;
                        attr.add(pair);
                    }
                    return attr;
                };
