                StiHtmlExportService.prototype.prepareChartData = function (writer, chart, width, height) {
                   
                    var painter = new StiContextPainter();
                    var context = new StiContext(painter, false, false, false, this.zoom);
                    var sb = new StringBuilder();
                    var sWriter = null;
                    var textWriter = null;
                    if (writer == null) {
                        textWriter = new TextWriter();
                        sWriter = new Export.StiHtmlTextWriter(textWriter);
                    }
                    else {
                        sWriter = writer;
                    }
                    var scale = 0.96;
                    this.prepareSvg(sWriter, Math.round2(height * scale, 2), Math.round2(width * scale, 2));
                    var pp = new Export.StiSvgData();
                    pp.x = 0;
                    pp.y = 0;
                    pp.width = (width * scale);
                    pp.height = (height * scale);
                    pp.component = chart;
                    var ms = new MemoryStream();
                    var xmlsWriter = new XmlTextWriter(Encoding.UTF8, ms);
                    Export.StiChartSvgHelper.writeChart(xmlsWriter, pp, this.zoom, this.chartType == Stimulsoft.Report.Export.StiHtmlChartType.AnimatedVector);
                    xmlsWriter.flush();
                    sWriter.write(Encoding.UTF8.getString(ms.toArray()));
                    sWriter.writeEndTag("svg");
                    this.getGuid(chart);
                    if (writer == null)
                        return textWriter.getStringBuilder().toString();
                    else
                        return null;
                };
