                StiImageExportService.prototype.exportImage = function (report, refString, settings) {
                    if (settings == null)
                        settings = this.getSettings();
                    //#region Export Dashboard
                    if (settings.getExportFormat() == Report.StiExportFormat.ImagePng && !report.isDocument && report.getCurrentPage().sti.is(IStiDashboard)) {
                        // Stimulsoft.Report.Dashboard.StiDashboardExport.export(report, refString, settings);
                        return;
                    }
                    //#endregion
                    try {
                        // StiExportUtils.DisableFontSmoothing();
                        this.exportImage1(report, refString, settings);
                    }
                    finally {
                        // StiExportUtils.EnableFontSmoothing(report);
                    }
                };
