            StiReport.prototype.isPackedFile = function (content) {
                if (!content)
                    return false;
                return ((content[0] == 0x1F && content[1] == 0x8B && content[2] == 0x08) ||
                    (content[0] == 0x50 && content[1] == 0x4B && content[2] == 0x03));
            };
            StiReport.prototype.load = function (param) {
                try {
                    if (param === undefined || param == null)
                        return;
                    if (param.sti.is(Array) || param.sti.is(Uint8Array)) {
                        if (this.isPackedFile(param)) {
                            this.loadPacked(param);
                            return;
                        }
                        param = Stimulsoft.System.Text.Encoding.UTF8.getString(param);
                    }
                    if (param.sti.is(String))
                        if (param.trim().sti.startsWith("<?xml"))
                            param = XmlConverter.toXml(param);
                    if (param.sti.is(XmlNode))
                        this.loadFromXmlInternal(param);
                    else
                        this.loadFromJsonInternal(param);
                }
                catch (exception) {
                    Stimulsoft.System.StiError.showError(exception, false);
                }
            };
