                StiChartHelper.getFilterData = function (report, filter, filterMethodName) {
                    try {
                        if (filter.item == StiFilterItem.Expression) {
                            var lowerName = filterMethodName.substr(0, 1).toLowerCase() + filterMethodName.substr(1);
                            if (report[filterMethodName] != null)
                                return report[filterMethodName]();
                            if (report[lowerName] != null)
                                return report[lowerName]();
                            var tempTxt = new StiText();
                            tempTxt.name = "*Chart_Filter*";
                            tempTxt.page = report.pages.getByIndex(0);
                            var parserResult = StiParser.parseTextValue("{" + filter.value + "}", tempTxt);
                            return parserResult;
                        }
                        switch (filter.dataType) {
                            case StiFilterDataType.String:
                                return filter.value;
                            case StiFilterDataType.Numeric:
                                return filter.value.sti.toNumber();
                            case StiFilterDataType.DateTime:
                                var result = DateTime.fromString(filter.value);
                                if (result != null) {
                                    return result;
                                }
                                break;
                            case StiFilterDataType.Boolean:
                                return filter.value.toLowerCase() == "true";
                        }
                    }
                    catch (ee) {
                        Stimulsoft.System.StiError.showError(ee.message, false);
                        // let error: string = StiString.format("Problem when parsing {0} {1} value\n", "Chart", filter);
                        // throw new Exception(error, ee);
                    }
                    return null;
                };
                StiChartHelper.getFilterResult = function (filter, itemArgument, itemValue, itemValueEnd, itemValueOpen, itemValueClose, itemValueLow, itemValueHigh, data) {
                    if (filter.item == StiFilterItem.Expression)
                        return data.sti.toBoolean();
                    var itemData = null;
                    switch (filter.item) {
                        case StiFilterItem.Argument:
                            itemData = itemArgument;
                            break;
                        case StiFilterItem.Value:
                            itemData = itemValue;
                            break;
                        case StiFilterItem.ValueEnd:
                            itemData = itemValueEnd;
                            break;
                        case StiFilterItem.ValueOpen:
                            itemData = itemValueOpen;
                            break;
                        case StiFilterItem.ValueClose:
                            itemData = itemValueClose;
                            break;
                        case StiFilterItem.ValueLow:
                            itemData = itemValueLow;
                            break;
                        case StiFilterItem.ValueHigh:
                            itemData = itemValueHigh;
                            break;
                    }
                    var result = false;
                    if (itemData != null) {
                        if (filter.dataType == StiFilterDataType.Numeric) {
                            itemData = itemData == null ? 0 : itemData.sti.toNumber();
                        }
                        else if (filter.dataType == StiFilterDataType.DateTime) {
                            var resultDateTime = DateTime.fromString(itemData.toString());
                            if (resultDateTime != null) {
                                itemData = resultDateTime;
                            }
                            else {
                                itemData = DateTime.fromOADate(itemData.sti.toNumber());
                            }
                        }
                        var comparable = itemData;
                        if (comparable != null && data != null) {
                            if (itemData.sti.getType() != data.sti.getType()) {
                                itemData = itemData.toString();
                                data = data.toString();
                                comparable = itemData;
                            }
                            try {
                                switch (filter.condition) {
                                    case StiFilterCondition.EqualTo:
                                        return comparable.sti.compareTo(data) == 0;
                                    case StiFilterCondition.NotEqualTo:
                                        return comparable.sti.compareTo(data) != 0;
                                    case StiFilterCondition.GreaterThan:
                                        return comparable.sti.compareTo(data) == 1;
                                    case StiFilterCondition.GreaterThanOrEqualTo:
                                        return comparable.sti.compareTo(data) >= 0;
                                    case StiFilterCondition.LessThan:
                                        return comparable.sti.compareTo(data) == -1;
                                    case StiFilterCondition.LessThanOrEqualTo:
                                        return comparable.sti.compareTo(data) <= 0;
                                    case StiFilterCondition.Containing:
                                        var str1 = itemData.toString();
                                        var str2 = data.toString();
                                        return str1.indexOf(str2) != -1;
                                    case StiFilterCondition.NotContaining:
                                        var str3 = itemData.toString();
                                        var str4 = data.toString();
                                        return str3.indexOf(str4) == -1;
                                    case StiFilterCondition.BeginningWith:
                                        var str5 = itemData.toString();
                                        var str6 = data.toString();
                                        return str5.sti.startsWith(str6);
                                    case StiFilterCondition.EndingWith:
                                        var str7 = itemData.toString();
                                        var str8 = data.toString();
                                        return str7.sti.endsWith(str8);
                                }
                            }
                            catch (e) {
                                Stimulsoft.System.StiError.showError(e, false);
                            }
                        }
                    }
                    return result;
                };
