                StiChartHelper.convertStringToColor = function (colorStr) {
                    var color = null;
                    if (colorStr != null) {
                        colorStr = colorStr.trim();
                        var separator = ",";
                        for (var index = 0; index < colorStr.length; index++) {
                            if (!(Char.isDigit(colorStr[index]) || Char.isWhitespace(colorStr[index]))) {
                                separator = colorStr[index];
                                break;
                            }
                        }
                        var rgb = colorStr.split(separator);
                        if (rgb.length == 3 || rgb.length == 4) {
                            try {
                                if (rgb.length == 3) {
                                    color = Color.fromArgb(parseInt(rgb[0].trim()), parseInt(rgb[1].trim()), parseInt(rgb[2].trim()));
                                }
                                else {
                                    color = Color.fromArgb(parseInt(rgb[0].trim()), parseInt(rgb[1].trim()), parseInt(rgb[2].trim()), parseInt(rgb[3].trim()));
                                }
                            }
                            catch (e) {
                                Stimulsoft.System.StiError.showError(e, false);
                                // let error: string = StiString.format("Can't get color from {0}", colorStr);
                                // StiLogService.Write("StiChartHelper.ConvertStringToColor " + error);
                                // throw new ArgumentException(error);
                            }
                        }
                        else {
                            try {
                                var result = parseInt(colorStr);
                                if (result >= 0) {
                                    // let color2: Color = Color.fromArgb(result);
                                    // if (result < 0xffffff) color2 = Color.fromArgb(0xff, color2.r, color2.g, color2.b);
                                    // return color2;
                                }
                                // let converter = new ColorConverter();
                                // return converter.ConvertFromString(colorStr);
                            }
                            catch (e) {
                                Stimulsoft.System.StiError.showError(e, false);
                                // let error: string = StiString.format("Can't get color from {0}", colorStr);
                                // StiLogService.Write("StiChartHelper.ConvertStringToColor " + error);
                                // throw new ArgumentException(error);
                            }
                        }
                    }
                    return color;
                };
