                    StiGaugeHelper.bulletGraphsGreen = function (gauge, report) {
                        this.initializeGauge(gauge, 300, 100);
                        var linearScale1 = new StiLinearScale();
                        linearScale1.relativeHeight = 0.94;
                        linearScale1.startWidth = 0.01;
                        linearScale1.endWidth = 0.01;
                        linearScale1.maximum = 100;
                        linearScale1.majorInterval = 20;
                        linearScale1.orientation = Orientation.Horizontal;
                        linearScale1.brush = new StiEmptyBrush();
                        linearScale1.borderBrush = new StiEmptyBrush();
                        var linearRangeList1 = new StiLinearRangeList();
                        var startValue = 0;
                        var index = 0;
                        while (++index < 11) {
                            var linearRange = new StiLinearRange();
                            linearRange.startValue = startValue;
                            startValue += 10;
                            linearRange.endValue = startValue;
                            linearRange.startWidth = 0.5;
                            linearRange.endWidth = 0.5;
                            linearRange.placement = Gauge.StiPlacement.Overlay;
                            linearRange.borderBrush = new StiSolidBrush(Color.fromArgb(150, 139, 138, 135));
                            if (index >= 1 && index <= 3)
                                linearRange.brush = new StiSolidBrush(Color.fromArgb(165, 214, 167));
                            else if (index >= 4 && index <= 7)
                                linearRange.brush = new StiSolidBrush(Color.fromArgb(76, 175, 80));
                            else
                                linearRange.brush = new StiSolidBrush(Color.fromArgb(46, 125, 50));
                            linearRangeList1.ranges.add(linearRange);
                        }
                        var linearTickLabelMajor1 = new StiLinearTickLabelMajor();
                        linearTickLabelMajor1.offset = 0.25;
                        var linearTickMarkCustom1 = new StiLinearTickMarkCustom();
                        linearTickMarkCustom1.placement = Gauge.StiPlacement.Overlay;
                        linearTickMarkCustom1.relativeWidth = 0.015;
                        linearTickMarkCustom1.relativeHeight = 0.3;
                        linearTickMarkCustom1.brush = new StiGradientBrush(Color.fromArgb(100, 100, 100), Color.fromArgb(10, 10, 10), 90);
                        linearTickMarkCustom1.valueObj = 80;
                        var linearBar1 = new StiLinearBar();
                        linearBar1.brush = new StiSolidBrush(Color.black);
                        linearBar1.startWidth = 0.1;
                        linearBar1.endWidth = 0.1;
                        linearScale1.items.add(linearRangeList1);
                        linearScale1.items.add(linearTickLabelMajor1);
                        linearScale1.items.add(linearTickMarkCustom1);
                        linearScale1.items.add(linearBar1);
                        gauge.scales.add(linearScale1);
                        this.initializeName(gauge, report);
                    };
